 function outlineControls(row,index){const reference=isOutlineReferenceChapter(row),enabled=data.contentMode!=='text'&&!reference,selection=flowPresentation(row.presentation);return `<div class="wf-outline-content" role="group" aria-label="第 ${index+1} 章内容形式">${flowPresentationKeys.map(key=>`<button type="button" id="wf-content-${esc(row.id)}-${key}" class="wf-content-toggle" data-wf-presentation="${key}" data-wf-outline-id="${esc(row.id)}" aria-label="第 ${index+1} 章${contentLabels[key]}" aria-pressed="${enabled&&selection[key]}" ${enabled?'':'disabled'}>${contentLabels[key]}</button>`).join('')}${reference?'<small>参考文献不生成扩展内容</small>':''}</div>`;}
