 function outlineEditor({embedded=false}={}){return `<h2>${embedded?'报告专属提纲':spec.steps[data.stage]}</h2><p class="wf-muted">选择 AI 生成专属提纲或上传已有提纲；生成或上传后可编辑章节。确认时按目标 ${Number(data.targetWords)} 字分配，参考文献不占正文字数。</p><div class="wf-outline-sources" role="group" aria-label="提纲创建方式"><button type="button" class="btn secondary wf-outline-source" data-wf-generate="outline" data-outline-mode="ai"><span aria-hidden="true">✦</span><span><b>AI 生成专属提纲</b><small>根据题目与研究资料生成章节结构</small></span><span aria-hidden="true">→</span></button><button type="button" class="btn secondary wf-outline-source" data-wf-upload="outline" data-outline-mode="upload"><span aria-hidden="true">↥</span><span><b>上传已有提纲</b><small>支持 DOCX、PDF 或 TXT 文件</small></span><span aria-hidden="true">→</span></button></div>${inlineOutline&&(data.jobs.outline?.itemId||data.jobs.outline?.commandKey)?'<div class="wf-actions"><button type="button" class="btn secondary" data-wf-recover="outline">查看已提交提纲任务</button></div>':''}${embedded?'<section data-wf-outline-ai hidden></section>':''}${contentOptions()}<div class="wf-outline">${data.outline.map((row,index)=>`<div class="wf-outline-row" data-wf-outline="${esc(row.id)}"><span>${String(index+1).padStart(2,'0')}</span><input data-wf-outline-title aria-label="第 ${index+1} 个章节标题" maxlength="300" value="${esc(row.title)}"><label>字数<input data-wf-outline-words aria-label="第 ${index+1} 个章节字数" type="number" min="0" step="1" value="${Number(row.targetWords)||0}"></label><button type="button" class="btn secondary" data-wf-remove-outline="${esc(row.id)}" aria-label="移除第 ${index+1} 个章节">×</button>${outlineControls(row,index)}</div>`).join('')||'<div class="wf-empty">请选择 AI 生成专属提纲或上传已有提纲。</div>'}</div>${data.outline.length?'<div class="wf-actions"><button type="button" class="btn secondary" data-wf-add-outline>添加章节</button><button type="button" class="btn secondary" data-wf-allocate>按目标字数分配</button></div>':''}<p class="wf-muted">当前分配合计 <strong>${data.outline.reduce((n,row)=>n+Number(row.targetWords||0),0)}</strong> / ${Number(data.targetWords)} 字 · 已有正文和历史版本会保留。</p>`;}
