 async function generateTopics(){if(jobPanel?.hasWork?.())return;if(parsing){setError('资料正在解析，请完成后再生成。');return;}try{topicSnapshot();}catch(e){setError(e.message);return;}jobPanel?.dispose();jobPanel=mountWritingJobPanel({container:$('[data-wf-topic-ai]'),ctx,kind:'idea',operation:'ideas',getSnapshot:topicSnapshot,getProjectRef:()=>data.projectId||'',initialState:data.jobs.topic||{},isCurrent:alive,onStateChange:async state=>{if(!alive())return false;data.jobs.topic=state;if(!save())return false;return hasDraftScope()?await saveAccountDraft():true;},onApply:async(output,item)=>{const ideas=validatedIdeas(output,3),key=topicKey(),previous={ideas:data.topicIdeas,meta:data.topicIdeasMeta};data.topicIdeas=ideas;data.topicIdeasMeta={ownerId:data.jobs.topic.ownerId,inputKey:key,jobId:item.id};try{await durableSave();}catch(e){data.topicIdeas=previous.ideas;data.topicIdeasMeta=previous.meta;save({captureUI:false});throw e;}if(topicKey()!==key)throw Error('保存期间选题条件已变化，请核对原任务后重新生成。');notice='已保存 3 个真实生成的候选题目，核对后可选用。';render();}});await jobPanel.generate();}
 async function chooseIdea(mode,index){capture();const rows=mode==='topic'?data.topicIdeas:data.ideaCandidates,meta=mode==='topic'?data.topicIdeasMeta:data.ideaCandidatesMeta,row=rows?.[index],before=mode==='topic'?topicKey():inputKey();if(!row||!meta?.ownerId||meta.inputKey!==before){setError('选题条件已有变化，请按当前信息重新生成或核对原任务。');return;}try{let value;if(ctx.api)value=await ctx.api('/auth/me');else{const response=await window.fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw Error('请先登录原账户。');value=await response.json();}if(!alive())return;if(value.user?.id!==meta.ownerId)throw Error('登录账户已变化，不能采用原账户的选题结果。');if((mode==='topic'?topicKey():inputKey())!==before)throw Error('确认期间选题条件已有变化，请重新核对。');const previous={title:data.title,stage:data.stage,unlocked:data.unlocked,completed:[...data.completed],outlineConfirmed:data.outlineConfirmed};data.title=row.title.trim();if($('#writing-title'))$('#writing-title').value=data.title;invalidateFrom('basic');data.stage=0;try{await durableSave();}catch(e){Object.assign(data,previous);if(alive()){const titleNode=$('#writing-title');if(titleNode?.value===row.title.trim())titleNode.value=data.title;capture();save({captureUI:false});render();}throw e;}notice='已选用候选题目，可继续完善写作要求。';render();}catch(e){if(alive())setError(e.message||'选题采用未完成。');}}
 function search(mode){capture();if(!data.title?.trim()){setError('请先填写题目。');return;}refDispose?.();refDispose=openWritingReferenceSearch({modal:ctx.modal,mode,context:{title:data.title,keywords:data.keywords,major:data.major},getExisting:()=>data.references,isActive:alive,onImport:(rows,{isCurrent})=>{if(!isCurrent()||!alive())return;invalidateFrom('references');data.references.push(...newReferenceSearchItems(rows,data.references).map(row=>({...row,url:safeReferenceURL(row.url),confirmed:false})));save({captureUI:false});render();}});}
