  $('[data-wf-citation-confirm]')?.addEventListener('click',()=>{capture();if(!citationPreview||citationPreview.input!==citationDraft){setError('粘贴内容已有变化，请重新预览后确认。');return;}try{const parsed=parseCitationImport(citationDraft,{existing:data.references});if(data.references.length+parsed.items.length>200)throw Error('参考文献总计最多 200 篇，请先移除不需要的题录。');if(!parsed.items.length)throw Error('这些题录已存在，请核对预览。');data.references.push(...parsed.items);citationDraft='';citationPreview=null;invalidateFrom('references');notice='引文题录已加入待核对列表；题录不代表已获得或已读全文。';save({captureUI:false});render();}catch(e){setError(e.message);}});
