  container.querySelectorAll('[data-wf-upload]').forEach(button=>button.onclick=()=>{$('#wf-file').dataset.mode=button.dataset.wfUpload;$('#wf-file').click();});$('#wf-file').onchange=e=>{const file=e.target.files?.[0];if(file)void importFile(file,e.target.dataset.mode);};
